package app.usspace.couple.v012;
import android.content.Context;
import android.content.pm.PackageManager;
import android.health.connect.*;
import android.health.connect.datatypes.*;
import android.os.*;
import androidx.work.*;
import com.google.firebase.auth.*;
import com.google.firebase.firestore.*;
import com.google.android.gms.tasks.Tasks;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;

/** Best-effort periodic reads only after separately granted background permission. */
public final class HealthBackgroundWorker extends Worker {
 public HealthBackgroundWorker(Context context,WorkerParameters params){super(context,params);}
 public Result doWork(){Context c=getApplicationContext();if(Build.VERSION.SDK_INT<34||c.checkSelfPermission("android.permission.health.READ_HEALTH_DATA_IN_BACKGROUND")!=PackageManager.PERMISSION_GRANTED)return Result.success();FirebaseUser actor=FirebaseAuth.getInstance().getCurrentUser();if(actor==null)return Result.success();String uid=actor.getUid();if(!c.getSharedPreferences("usspace.health.accounts",0).getBoolean("connected:"+uid,false)||!c.getSharedPreferences("usspace.health.accounts",0).getBoolean("background:"+uid,false))return Result.success();HealthConnectManager manager=c.getSystemService(HealthConnectManager.class);if(manager==null)return Result.success();Instant now=Instant.now(),start=HealthSyncPolicy.dayStart(now,ZoneId.systemDefault());FirebaseFirestore db=FirebaseFirestore.getInstance();
  try{for(String category:Arrays.asList("steps","sleep","workouts","heartRate")){Map<String,Object> value=null;String measuredAt=now.toString();
    if(category.equals("steps")&&granted(c,"STEPS")){CountDownLatch latch=new CountDownLatch(1);List<Long> values=new ArrayList<>();manager.aggregate(new AggregateRecordsRequest.Builder<Long>(range(start,now)).addAggregationType(StepsRecord.STEPS_COUNT_TOTAL).addDataOriginsFilter(samsung()).build(),Runnable::run,new OutcomeReceiver<AggregateRecordsResponse<Long>,HealthConnectException>(){public void onResult(AggregateRecordsResponse<Long> response){Long v=response.get(StepsRecord.STEPS_COUNT_TOTAL);if(v!=null)values.add(v);latch.countDown();}public void onError(HealthConnectException e){latch.countDown();}});if(latch.await(20,TimeUnit.SECONDS)&&!values.isEmpty())value=Map.of("value",values.get(0));}
    if(category.equals("sleep")&&granted(c,"SLEEP")){List<SleepSessionRecord> rows=read(manager,SleepSessionRecord.class,now.minusSeconds(2*86400),now);SleepSessionRecord latest=rows.stream().max(Comparator.comparing(SleepSessionRecord::getEndTime)).orElse(null);if(latest!=null){value=Map.of("hours",Duration.between(latest.getStartTime(),latest.getEndTime()).toMinutes()/60.0);measuredAt=latest.getEndTime().toString();}}
    if(category.equals("workouts")&&granted(c,"EXERCISE")){List<ExerciseSessionRecord> rows=read(manager,ExerciseSessionRecord.class,start,now);if(!rows.isEmpty()){List<long[]> spans=new ArrayList<>();for(ExerciseSessionRecord r:rows)spans.add(new long[]{r.getStartTime().toEpochMilli(),r.getEndTime().toEpochMilli()});value=Map.of("count",rows.size(),"minutes",HealthSyncPolicy.coveredMillis(spans,start.toEpochMilli(),now.toEpochMilli())/60000.0);}}
    if(category.equals("heartRate")&&granted(c,"HEART_RATE")){List<HeartRateRecord> rows=read(manager,HeartRateRecord.class,now.minusSeconds(7*86400),now);HeartRateRecord.HeartRateSample latest=null;for(HeartRateRecord r:rows)for(HeartRateRecord.HeartRateSample s:r.getSamples())if(latest==null||s.getTime().isAfter(latest.getTime()))latest=s;if(latest!=null){value=Map.of("bpm",latest.getBeatsPerMinute());measuredAt=latest.getTime().toString();}}
    if(value==null)continue;FirebaseUser current=FirebaseAuth.getInstance().getCurrentUser();if(current==null||!uid.equals(current.getUid())||!c.getSharedPreferences("usspace.health.accounts",0).getBoolean("connected:"+uid,false)||!c.getSharedPreferences("usspace.health.accounts",0).getBoolean("background:"+uid,false))return Result.success();cachePrivate(c,uid,category,value,measuredAt);DocumentSnapshot consent;try{consent=Tasks.await(db.document("users/"+uid+"/careConsent/"+category).get(Source.SERVER),5,TimeUnit.SECONDS);}catch(Exception unavailable){continue;}if(!Boolean.TRUE.equals(consent.getBoolean("enabled")))continue;Map<String,Object> record=new HashMap<>();record.put("ownerUid",uid);record.put("pairId",consent.getString("pairId"));record.put("category",category);record.put("consentRevision",consent.getLong("revision"));record.put("value",value);record.put("measuredAt",measuredAt);record.put("source","Samsung Health via Health Connect");record.put("updatedAt",FieldValue.serverTimestamp());
    // Firestore checks the current consent revision and both membership generations,
    // even if permission was revoked while this worker was reading the provider.
    try{Tasks.await(db.document("users/"+uid+"/careShares/"+category).set(record),5,TimeUnit.SECONDS);}catch(Exception consentOrNetworkChanged){/* Private sync is complete; never retry with a different consent revision. */}
  }return Result.success();}catch(Exception transientFailure){return Result.retry();}
 }
 private static void cachePrivate(Context c,String uid,String category,Map<String,Object> value,String measuredAt)throws Exception{android.content.SharedPreferences prefs=c.getSharedPreferences("usspace.health.background",0);org.json.JSONObject snapshot;try{snapshot=new org.json.JSONObject(prefs.getString("snapshot:"+uid,"{}"));}catch(Exception invalid){snapshot=new org.json.JSONObject();}String day=java.time.LocalDate.now().toString();if(!day.equals(snapshot.optString("date")))snapshot=new org.json.JSONObject();org.json.JSONArray available=snapshot.optJSONArray("availableFields");if(available==null)available=new org.json.JSONArray();org.json.JSONObject times=snapshot.optJSONObject("fieldTimes"),states=snapshot.optJSONObject("fieldStates");if(times==null)times=new org.json.JSONObject();if(states==null)states=new org.json.JSONObject();String field=category.equals("heartRate")?"hr":category.equals("workouts")?"workout":category;
  if(category.equals("steps"))snapshot.put("steps",value.get("value"));if(category.equals("sleep"))snapshot.put("sleep",value.get("hours"));if(category.equals("heartRate")){snapshot.put("hr",value.get("bpm"));snapshot.put("hrType","recent");}if(category.equals("workouts")){snapshot.put("workoutCount",value.get("count"));snapshot.put("workoutMinutes",value.get("minutes"));snapshot.put("workout",value.get("count")+" workouts · "+value.get("minutes")+" min");}
  boolean exists=false;for(int i=0;i<available.length();i++)if(field.equals(available.optString(i)))exists=true;if(!exists)available.put(field);times.put(field,measuredAt);states.put(field,"ready");snapshot.put("uid",uid);snapshot.put("date",day);snapshot.put("availableFields",available);snapshot.put("fieldTimes",times);snapshot.put("fieldStates",states);snapshot.put("state","partial");snapshot.put("source","Samsung Health via Health Connect");snapshot.put("syncedAt",java.time.Instant.now().toString());prefs.edit().putString("snapshot:"+uid,snapshot.toString()).apply();
 }
 private static boolean granted(Context c,String name){return c.checkSelfPermission("android.permission.health.READ_"+name)==PackageManager.PERMISSION_GRANTED;}
 private static DataOrigin samsung(){return new DataOrigin.Builder().setPackageName(HealthSyncPolicy.SAMSUNG_PACKAGE).build();}
 private static TimeInstantRangeFilter range(Instant a,Instant b){return new TimeInstantRangeFilter.Builder().setStartTime(a).setEndTime(b).build();}
 private static <T extends android.health.connect.datatypes.Record> List<T> read(HealthConnectManager m,Class<T> type,Instant a,Instant b)throws Exception{List<T> all=new ArrayList<>();long token=-1;for(int page=0;page<10;page++){CountDownLatch latch=new CountDownLatch(1);List<ReadRecordsResponse<T>> answer=new ArrayList<>();ReadRecordsRequestUsingFilters.Builder<T> builder=new ReadRecordsRequestUsingFilters.Builder<>(type).addDataOrigins(samsung()).setTimeRangeFilter(range(a,b)).setPageSize(500);if(token!=-1)builder.setPageToken(token);m.readRecords(builder.build(),Runnable::run,new OutcomeReceiver<ReadRecordsResponse<T>,HealthConnectException>(){public void onResult(ReadRecordsResponse<T> r){answer.add(r);latch.countDown();}public void onError(HealthConnectException e){latch.countDown();}});if(!latch.await(15,TimeUnit.SECONDS)||answer.isEmpty())throw new IllegalStateException("read-unavailable");for(T r:answer.get(0).getRecords())if(HealthSyncPolicy.SAMSUNG_PACKAGE.equals(r.getMetadata().getDataOrigin().getPackageName()))all.add(r);token=answer.get(0).getNextPageToken();if(token==-1)return all;}throw new IllegalStateException("read-partial");}
}
